window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c308a6c04a0d70ba"]={"versions": [{"id": "FIG-c308a6c04a0d70ba", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablauf-/Flussdiagramm) zur Darstellung des Empfangsdatenflusses (Receive Data Flow) im AUTOSAR Classic Platform CAN-Stack. Das Diagramm ordnet die Prozessschritte vertikal den beteiligten Architekturschichten bzw. -modulen über seitlich angeordnete Dokument-/Partitions-Symbole zu: CAN Controller, CAN Driver (MCAL), CAN Interface (CanIf, BSW Communication Services) und Upper Layer (z. B. PduR, CanNm, CanTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module / Entitäten:</strong></li>\n<li><code>CAN Controller</code>: Hardware-Einheit zum Empfang von CAN-Frames.</li>\n<li><code>CAN Driver</code>: MCAL-Treiber zur Interrupt-Behandlung und Datenpufferung (<code>«datastore» Temporary buffer in CAN Driver</code>).</li>\n<li><code>CAN Interface</code> (<code>CanIf</code>): Vermittlungsschicht für Software-Filterung, DLC-Prüfung und Weiterleitung.</li>\n<li><code>Dem</code> (Diagnostic Event Manager): Fehlerberichterstattung bei ungültiger DLC.</li>\n<li><code>Upper Layer</code>: Empfänger der Nutzdaten (z. B. PduR, CanNm) mit Datenpuffer (<code>«datastore» Copy data to L-PDU buffer</code>).</li>\n<li><strong>Funktionen & Schnittstellen:</strong></li>\n<li><code>Receive Interrupt</code>: Hardware-Interrupt des CAN Controllers.</li>\n<li><code>CanIf_RxIndication()</code>: Callback-Schnittstelle des CAN Interface, aufgerufen durch den CAN Driver.</li>\n<li><code>&lt;User_RxIndication&gt;()</code>: Konfigurierbare Rx-Indication-Schnittstelle an übergeordnete Schichten.</li>\n<li><code>Dem_ReportErrorStatus(CANIF_E_INVALID_DLC, ...)</code>: API-Aufruf zur Fehlermeldung bei fehlerhafter DLC.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start & Hardware-Ebene:</strong> Der Ablauf beginnt beim Initialknoten mit einem <code>Receive Interrupt</code> des CAN Controllers.</li>\n<li><strong>CAN Driver:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Entscheidung <code>Data normalization necessary?</code>: Falls <code>[Yes]</code>, Zwischenspeicherung in <code>«datastore» Temporary buffer in CAN Driver</code>; falls <code>[No]</code>, direkter Übergang.</li>\n<li>Aufruf von <code>CanIf_RxIndication()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>CAN Interface:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung <code>Rx L-PDU received in BasicCAN ?</code>:</li>\n<li>Wenn <code>[Yes]</code>: Ausführung von <code>Software filtering</code>. Bei Ergebnis <code>[L-PDU not passed]</code> führt der Pfad direkt zur Synchronization Bar (Ende). Bei <code>[L-PDU passed]</code> Weiterführung zur DLC-Prüfung.</li>\n<li>Wenn <code>[No]</code> (FullCAN-Empfang): Direkte Weiterführung zur DLC-Prüfung.</li>\n<li>Verzweigung <code>CANIF_DLC_CHECK enabled?</code>:</li>\n<li>Wenn <code>[Yes]</code>: Verzweigung <code>DLC Check failed ?</code>.</li>\n<li>Falls <code>[Yes]</code>: Aufruf <code>Call Dem_ReportErrorStatus() with EventId == CANIF_E_INVALID_DLC</code>, danach Weiterleitung an die Synchronization Bar.</li>\n<li>Falls <code>[No]</code>: Weiterführung zu <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n<li>Wenn <code>[No]</code>: Direkte Weiterführung zu <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Upper Layer & Pufferung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n<li>Speicherung im Datenpuffer via <code>«datastore» Copy data to L-PDU buffer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung der Pfade (verworfen durch Software-Filterung, abgebrochen nach DLC-Fehler, erfolgreiche Zustellung) an einer Synchronization/Join-Bar.</li>\n<li>Rückkehr der Aufrufe (<code>&lt;User_RxIndication&gt;() returns</code>, <code>CanIf_RxIndication() returns</code>) zum Activity Final Node.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DLC-Validierung:</strong> Ist <code>CANIF_DLC_CHECK</code> aktiviert, führt ein Längenfehler zwingend zum Melden von <code>CANIF_E_INVALID_DLC</code> an das Dem und bricht die Weitergabe an übergeordnete Schichten ab.</li>\n<li><strong>Filterung:</strong> BasicCAN erfordert Software-Filterung im CanIf; nicht passende L-PDUs werden still verworfen (ohne Dem-Fehler).</li>\n<li><strong>Synchronität:</strong> Der Pfad veranschaulicht den synchronen Kontext ausgehend vom Empfangs-Interrupt über CanIf bis in die oberen Schichten inklusive Pufferung vor Rückkehr der Indication-Funktionen.</li>\n</ul>"}, {"id": "FIG-c7ace990ae36d0b8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablauf-/Flussdiagramm) zur Darstellung des Empfangsdatenflusses (Receive Data Flow) im AUTOSAR Classic Platform CAN-Stack. Das Diagramm ordnet die Prozessschritte vertikal den beteiligten Architekturschichten bzw. -modulen über seitlich angeordnete Dokument-/Partitions-Symbole zu: CAN Controller, CAN Driver (MCAL), CAN Interface (CanIf, BSW Communication Services) und Upper Layer (z. B. PduR, CanNm, CanTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module / Entitäten:</strong></li>\n<li><code>CAN Controller</code>: Hardware-Einheit zum Empfang von CAN-Frames.</li>\n<li><code>CAN Driver</code>: MCAL-Treiber zur Interrupt-Behandlung und Datenpufferung (<code>«datastore» Temporary buffer in CAN Driver</code>).</li>\n<li><code>CAN Interface</code> (<code>CanIf</code>): Vermittlungsschicht für Software-Filterung, DLC-Prüfung und Weiterleitung.</li>\n<li><code>Dem</code> (Diagnostic Event Manager): Fehlerberichterstattung bei ungültiger DLC.</li>\n<li><code>Upper Layer</code>: Empfänger der Nutzdaten (z. B. PduR, CanNm) mit Datenpuffer (<code>«datastore» Copy data to L-PDU buffer</code>).</li>\n<li><strong>Funktionen & Schnittstellen:</strong></li>\n<li><code>Receive Interrupt</code>: Hardware-Interrupt des CAN Controllers.</li>\n<li><code>CanIf_RxIndication()</code>: Callback-Schnittstelle des CAN Interface, aufgerufen durch den CAN Driver.</li>\n<li><code>&lt;User_RxIndication&gt;()</code>: Konfigurierbare Rx-Indication-Schnittstelle an übergeordnete Schichten.</li>\n<li><code>Dem_ReportErrorStatus(CANIF_E_INVALID_DLC, ...)</code>: API-Aufruf zur Fehlermeldung bei fehlerhafter DLC.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start & Hardware-Ebene:</strong> Der Ablauf beginnt beim Initialknoten mit einem <code>Receive Interrupt</code> des CAN Controllers.</li>\n<li><strong>CAN Driver:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Entscheidung <code>Data normalization necessary?</code>: Falls <code>[Yes]</code>, Zwischenspeicherung in <code>«datastore» Temporary buffer in CAN Driver</code>; falls <code>[No]</code>, direkter Übergang.</li>\n<li>Aufruf von <code>CanIf_RxIndication()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>CAN Interface:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung <code>Rx L-PDU received in BasicCAN ?</code>:</li>\n<li>Wenn <code>[Yes]</code>: Ausführung von <code>Software filtering</code>. Bei Ergebnis <code>[L-PDU not passed]</code> führt der Pfad direkt zur Synchronization Bar (Ende). Bei <code>[L-PDU passed]</code> Weiterführung zur DLC-Prüfung.</li>\n<li>Wenn <code>[No]</code> (FullCAN-Empfang): Direkte Weiterführung zur DLC-Prüfung.</li>\n<li>Verzweigung <code>CANIF_DLC_CHECK enabled?</code>:</li>\n<li>Wenn <code>[Yes]</code>: Verzweigung <code>DLC Check failed ?</code>.</li>\n<li>Falls <code>[Yes]</code>: Aufruf <code>Call Dem_ReportErrorStatus() with EventId == CANIF_E_INVALID_DLC</code>, danach Weiterleitung an die Synchronization Bar.</li>\n<li>Falls <code>[No]</code>: Weiterführung zu <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n<li>Wenn <code>[No]</code>: Direkte Weiterführung zu <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Upper Layer & Pufferung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>Call &lt;User_RxIndication&gt;() to upper layers</code>.</li>\n<li>Speicherung im Datenpuffer via <code>«datastore» Copy data to L-PDU buffer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung der Pfade (verworfen durch Software-Filterung, abgebrochen nach DLC-Fehler, erfolgreiche Zustellung) an einer Synchronization/Join-Bar.</li>\n<li>Rückkehr der Aufrufe (<code>&lt;User_RxIndication&gt;() returns</code>, <code>CanIf_RxIndication() returns</code>) zum Activity Final Node.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DLC-Validierung:</strong> Ist <code>CANIF_DLC_CHECK</code> aktiviert, führt ein Längenfehler zwingend zum Melden von <code>CANIF_E_INVALID_DLC</code> an das Dem und bricht die Weitergabe an übergeordnete Schichten ab.</li>\n<li><strong>Filterung:</strong> BasicCAN erfordert Software-Filterung im CanIf; nicht passende L-PDUs werden still verworfen (ohne Dem-Fehler).</li>\n<li><strong>Synchronität:</strong> Der Pfad veranschaulicht den synchronen Kontext ausgehend vom Empfangs-Interrupt über CanIf bis in die oberen Schichten inklusive Pufferung vor Rückkehr der Indication-Funktionen.</li>\n</ul>"}], "trans": [{"from": "FIG-c308a6c04a0d70ba", "to": "FIG-c7ace990ae36d0b8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
